/* Mobile first — Grid for page structure, Flexbox inside components */
:root { --bg: #090909; --surface: #111112; --text: #eee9e5; --muted: #9c9596; --wine: #841b30; --accent: #b4465d; --line: #2c2729; --gutter: 20px; --cover-sheet: url("data:image/png;base64,"); }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: 24px; }
body { margin: 0; background: var(--bg); color: var(--text); font-family: Arial, Helvetica, sans-serif; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto 1fr auto; }
main { display: grid; grid-template-columns: minmax(0, 1fr); }
a { color: inherit; text-decoration: none; }
button, input, textarea { font: inherit; }
button { cursor: pointer; }
button, a, input, textarea { -webkit-tap-highlight-color: transparent; }
img { display: block; max-width: 100%; }
h1, h2, h3, p { margin: 0; }
.wrap { width: calc(100% - var(--gutter) * 2); max-width: 1600px; margin-inline: auto; }
.section { padding-block: 60px; }
a:focus-visible, button:focus-visible, .gallery:focus-visible { outline: 2px solid var(--text); outline-offset: 5px; }
.skip-link { position: fixed; top: -100px; left: 20px; padding: 14px; background: white; color: black; z-index: 20; }
.skip-link:focus { top: 15px; }
.header { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 20px; min-height: 96px; border-bottom: 1px solid var(--line); }
.brand { display: flex; align-items: center; gap: 8px; width: fit-content; min-height: 64px; }
.brand img { width: 58px; height: 58px; object-fit: contain; }
.brand > span { font-size: 12px; font-weight: 800; line-height: 1.2; letter-spacing: -.02em; }
.nav, .header-contact { display: none; }
.hamburger { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 7px; width: 48px; height: 48px; border: 1px solid var(--line); background: transparent; color: var(--text); }
.hamburger span { width: 22px; height: 1px; background: currentColor; }
.hero { display: grid; grid-template-columns: minmax(0, 1fr); gap: 38px; padding-block: 24px 35px; }
.hero-meta { display: flex; justify-content: space-between; gap: 20px; font: 10px/1.5 monospace; letter-spacing: .06em; }
.hero-meta span:last-child { display: none; }
h1 { font-family: Impact, 'Arial Narrow', Arial, sans-serif; font-weight: 900; font-size: clamp(38px, 10.6vw, 148px); line-height: .92; letter-spacing: -.045em; color: var(--wine); }
h1 > span { display: block; }
.title-second { color: var(--text); }
.hero-bottom { display: grid; grid-template-columns: 1fr; gap: 22px; }
.hero-bottom p { font-size: 16px; line-height: 1.4; }
.text-link { display: inline-flex; align-items: center; gap: 32px; min-height: 44px; width: fit-content; font-size: 14px; transition: color .25s; }
.text-link:hover { color: #db7588; }
.text-link > span { font-size: 23px; }
.hero-location { display: none; font: 11px/1.5 monospace; color: var(--muted); }
.eyebrow { display: block; font: 11px/1.5 monospace; letter-spacing: .06em; color: var(--muted); margin-bottom: 18px; }
.section-heading { display: grid; grid-template-columns: minmax(0, 1fr); gap: 24px; margin-bottom: 26px; }
h2 { font-size: clamp(29px, 5vw, 57px); line-height: 1.05; letter-spacing: -.045em; font-weight: 500; }
.work { padding-top: 30px; }
.gallery-controls { display: flex; align-items: center; gap: 10px; }
.counter { margin-right: auto; font: 12px monospace; color: var(--muted); }
.round-button { display: flex; justify-content: center; align-items: center; width: 48px; height: 48px; flex-shrink: 0; border: 1px solid #51434a; border-radius: 50%; background: transparent; color: var(--text); font-size: 24px; transition: background .25s, border-color .25s; }
.round-button:hover { background: var(--wine); border-color: var(--wine); }
.round-button:disabled { opacity: .3; cursor: default; background: transparent; }
/* Horizontal Grid gallery — swipe on touchscreens, native scroll without JS */
.gallery { --card-size: 86%; display: grid; grid-auto-flow: column; grid-auto-columns: var(--card-size); grid-template-rows: auto; gap: 16px; width: 100%; min-width: 0; overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x mandatory; scroll-padding-inline: var(--gutter); padding: 6px var(--gutter) 24px; scrollbar-width: thin; scrollbar-color: var(--wine) var(--bg); }
.gallery::after { content: ''; width: calc(100vw - var(--gutter) * 2 - (100vw - var(--gutter) * 2) * .86); }
.project { display: flex; flex-direction: column; gap: 17px; min-width: 0; scroll-snap-align: start; }
.project-preview { position: relative; display: block; width: 100%; aspect-ratio: 16 / 10; overflow: hidden; background: #171315; color: white; padding: 0; border: 0; text-align: left; }
.concept-cover, .custom-cover, .project-preview video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.concept-cover { background-image: var(--cover-sheet); background-size: 400% auto; transition: transform .6s ease, filter .6s ease; filter: saturate(.8) brightness(.85); }
.concept-cover[hidden] { display: none; }
.frame-1 { background-position: 0% 17.35%; } .frame-2 { background-position: 33.333% 17.35%; } .frame-3 { background-position: 66.667% 17.35%; } .frame-4 { background-position: 100% 17.35%; }
.frame-5 { background-position: 0% 82.65%; } .frame-6 { background-position: 33.333% 82.65%; } .frame-7 { background-position: 66.667% 82.65%; } .frame-8 { background-position: 100% 82.65%; }
.project-preview:hover .concept-cover { transform: scale(1.035); filter: saturate(1) brightness(1); }
.project-preview video { opacity: 0; transition: opacity .3s; pointer-events: none; }
.project-preview.is-playing video { opacity: 1; }
.frame-index { position: absolute; top: 16px; left: 16px; padding: 5px 7px; background: #09090980; font: 12px monospace; }
.preview-icon { position: absolute; bottom: 16px; right: 16px; width: 44px; height: 44px; display: flex; justify-content: center; align-items: center; border: 1px solid #ffffff80; border-radius: 50%; font-size: 22px; background: #09090940; }
.preview-label { position: absolute; bottom: 27px; left: 16px; font: 11px monospace; text-transform: uppercase; letter-spacing: .08em; opacity: 0; transition: opacity .25s; background: #09090980; padding: 5px; }
.project-preview:hover .preview-label, .project-preview:focus-visible .preview-label { opacity: 1; }
.project-caption { display: flex; flex-direction: column; gap: 7px; }
.project-caption h3 { font-size: 23px; font-weight: 500; letter-spacing: -.035em; }
.project-caption > span { font-size: 12px; color: var(--muted); }
.gallery-bottom { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 14px; margin-top: 22px; font: 10px/1.5 monospace; color: var(--muted); }
.gallery-status { min-height: 15px; }
.gallery-note { width: 100%; }
.about { display: grid; grid-template-columns: minmax(0, 1fr); gap: 22px; border-top: 1px solid var(--line); }
.about-copy { display: flex; flex-direction: column; align-items: flex-start; gap: 24px; }
.about-copy p { max-width: 680px; font-size: 17px; color: #b9b1b3; line-height: 1.6; }
.about-copy .text-link { margin-top: 6px; }
.services { border-top: 1px solid var(--line); }
.services-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 0; }
.service { display: flex; flex-direction: column; align-items: flex-start; padding: 30px 0; border-top: 1px solid var(--line); }
.service > span { color: #d16c80; font: 12px monospace; margin-bottom: 30px; }
.service h3 { font-size: 26px; font-weight: 500; letter-spacing: -.03em; }
.service p { font-size: 16px; color: var(--muted); line-height: 1.6; margin: 20px 0 30px; }
.service small { margin-top: auto; font: 10px/1.5 monospace; }
.contact { background: #641323; }
.contact-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 38px; }
.contact .eyebrow { color: #d8aeb7; }
.contact h2 { font-family: Impact, 'Arial Narrow', Arial, sans-serif; font-size: clamp(39px, 10vw, 78px); line-height: .99; font-weight: 900; }
.contact-copy p { margin-top: 25px; font-size: 16px; line-height: 1.5; color: #e6c6ce; }
.contact-form { display: grid; grid-template-columns: minmax(0, 1fr); gap: 24px; }
.field { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
label { font-size: 13px; }
input, textarea { width: 100%; min-width: 0; min-height: 52px; padding: 15px; border: 1px solid #b47986; border-radius: 0; background: #3c0e18; color: white; transition: background .25s, border-color .25s, box-shadow .25s; }
textarea { min-height: 140px; resize: vertical; }
input::placeholder, textarea::placeholder { color: #c6a1aa; opacity: 1; }
input:hover, textarea:hover { border-color: #e4b9c3; background: #45131e; }
input:focus, textarea:focus { outline: none; border-color: white; box-shadow: 0 0 0 2px #ffffff40; background: #2c0b12; }
.send-button { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 56px; padding: 16px 20px; border: 1px solid var(--text); background: var(--text); color: #220910; transition: background .25s, color .25s; }
.send-button:hover { background: #1b090e; color: white; }
.send-button:focus { outline: 2px solid white; outline-offset: 4px; }
.send-button span { font-size: 24px; line-height: 1; }
.form-note { color: #dfbdc5; font-size: 12px; line-height: 1.5; }
.footer { display: grid; grid-template-columns: 1fr auto; gap: 15px; padding-block: 28px; align-items: center; font: 11px monospace; color: var(--muted); }
.footer-brand { color: var(--text); }
.footer a { display: flex; align-items: center; min-height: 44px; width: fit-content; grid-column: 1 / -1; }
/* Intro is decorative and never blocks navigation; CSS hides it even without JS */
.intro { position: fixed; inset: 0; z-index: 15; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 20px; background: #641323; pointer-events: none; animation: curtain 1.6s cubic-bezier(.76,0,.24,1) both; }
.intro > span { font-family: Impact, Arial, sans-serif; font-size: clamp(80px, 23vw, 280px); font-weight: 900; letter-spacing: -.05em; animation: title-in .7s ease both; }
.intro small { font: 10px monospace; letter-spacing: .15em; }
.intro-seen .intro { display: none; }
.hero h1 { animation: reveal-title 1s .65s cubic-bezier(.2,.7,.2,1) both; }
.intro-seen .hero h1 { animation-delay: 0s; }
@keyframes title-in { from { opacity: 0; transform: translateY(35px); } to { opacity: 1; transform: translateY(0); } }
@keyframes curtain { 0%, 55% { clip-path: inset(0 0 0 0); opacity: 1; visibility: visible; } 99% { opacity: 1; } 100% { clip-path: inset(0 0 100% 0); opacity: 0; visibility: hidden; } }
@keyframes reveal-title { from { clip-path: inset(100% 0 0 0); transform: translateY(18px); } to { clip-path: inset(0 0 0 0); transform: translateY(0); } }
/* Tablet: 768–1199px */
@media (min-width: 768px) {
  :root { --gutter: 36px; }
  .section { padding-block: 78px; }
  .header { grid-template-columns: 1fr auto; min-height: 108px; }
  .brand img { width: 68px; height: 68px; }
  .nav { display: flex; gap: 32px; align-items: center; }
  .nav a { display: flex; align-items: center; min-height: 44px; font: 12px monospace; text-transform: uppercase; transition: color .25s; }
  .nav a:hover { color: #d16c80; }
  .hamburger { display: none; }
  .hero { gap: 42px; padding-block: 27px 35px; }
  .hero-meta { font-size: 11px; }
  .hero-meta span:last-child { display: inline; }
  h1 { font-size: clamp(76px, 11vw, 132px); }
  .hero-bottom { grid-template-columns: 1fr auto 1fr; align-items: end; }
  .hero-location { display: block; text-align: right; }
  .section-heading { grid-template-columns: minmax(0, 1fr) auto; align-items: end; }
  .counter { margin-right: 20px; }
  .work { padding-top: 38px; }
  .gallery { --card-size: 65%; gap: 24px; }
  .gallery::after { width: calc((100vw - var(--gutter) * 2) * .35); }
  .project-caption { flex-direction: row; justify-content: space-between; align-items: baseline; gap: 15px; }
  .gallery-note { width: auto; }
  .about { grid-template-columns: 1fr 2fr; gap: 40px; }
  .services-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 28px; }
  .service:last-child { grid-column: 1 / -1; }
  .contact-form { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .field-wide { grid-column: 1 / -1; }
  .footer { grid-template-columns: 1fr auto 1fr; }
  .footer a { grid-column: 3; justify-self: end; }
}
/* Desktop: 1200px and wider */
@media (min-width: 1200px) {
  :root { --gutter: 56px; }
  .section { padding-block: 96px; }
  .header { grid-template-columns: 1fr auto 1fr; }
  .header-contact { display: flex; align-items: center; justify-self: end; gap: 35px; min-height: 44px; font: 12px monospace; text-transform: uppercase; }
  .header-contact:hover { color: #d16c80; }
  .hero { padding-top: 26px; gap: 34px; }
  h1 { font-size: clamp(120px, 11.05vw, 177px); line-height: .88; }
  .hero-bottom p { font-size: 18px; }
  .work { padding-top: 32px; }
  .gallery { --card-size: 54%; gap: 30px; padding-left: max(var(--gutter), calc((100vw - 1600px) / 2)); scroll-padding-left: max(var(--gutter), calc((100vw - 1600px) / 2)); }
  .gallery::after { width: calc((100vw - var(--gutter) * 2) * .46); }
  .project-caption h3 { font-size: 28px; }
  .about { grid-template-columns: 1fr 2fr; gap: 80px; }
  .about-copy p { font-size: 20px; }
  .services-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 48px; }
  .service:last-child { grid-column: auto; }
  .service h3 { font-size: 30px; }
  .contact-grid { grid-template-columns: 1fr 1fr; gap: 80px; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { animation: none !important; transition: none !important; }
  .intro { display: none; }
}
